
-- Update existing courses that may have different USA rankings
UPDATE public.golf_courses 
SET usa_rank = 1, description = 'Cypress Point stuns with dramatic coastal terrain where the Santa Lucia Mountains meet the Pacific. Every hole offers exhilarating elevation changes and panoramic ocean views.'
WHERE name = 'Cypress Point Club' AND country = 'United States';

UPDATE public.golf_courses 
SET usa_rank = 2, description = 'Pine Valley is George Crump''s legacy to the game—unforgiving, strategic, and brilliantly executed. Widely regarded as the pinnacle of penal golf architecture.'
WHERE name = 'Pine Valley Golf Club' AND country = 'United States';

UPDATE public.golf_courses 
SET usa_rank = 3, description = 'Shinnecock Hills holds a unique place in golf history, not only for its role in founding the USGA but also as the site of one of the first purpose-built clubhouses.'
WHERE name = 'Shinnecock Hills Golf Club' AND country = 'United States';

UPDATE public.golf_courses 
SET usa_rank = 4, description = 'National Golf Links of America is a masterpiece of early 20th-century design—part tribute, part benchmark for modern architects, and all classic charm.'
WHERE name = 'National Golf Links of America' AND country = 'United States';

UPDATE public.golf_courses 
SET usa_rank = 5, description = 'Oakmont is as brutal as it is brilliant. A beast of a course that''s hosted more majors than any in the U.S. outside Augusta—and tests the best every time.'
WHERE name = 'Oakmont Country Club' AND country = 'United States';

UPDATE public.golf_courses 
SET usa_rank = 6, description = 'Sand Hills offers a spiritual kind of golf—a course built on simplicity, natural design, and a proud resistance to commercial fanfare.'
WHERE name = 'Sand Hills Golf Club' AND country = 'United States';

UPDATE public.golf_courses 
SET usa_rank = 7, description = 'Merion may be old, but it''s far from outdated. This Philadelphia gem evolved from cricket-playing roots to host some of the game''s most storied moments.'
WHERE name = 'Merion Golf Club (East)' AND country = 'United States';

UPDATE public.golf_courses 
SET usa_rank = 8, description = 'Augusta National is where golf''s finest minds met perfection. Jones and MacKenzie created more than just a course—they created legend.'
WHERE name = 'Augusta National Golf Club' AND country = 'United States';

UPDATE public.golf_courses 
SET usa_rank = 9, description = 'Los Angeles Country Club''s North Course lives up to its postcode. Elegant, exclusive, and architecturally rich—it''s a course that matches its prestigious setting.'
WHERE name = 'Los Angeles Country Club (North)' AND country = 'United States';

UPDATE public.golf_courses 
SET usa_rank = 10, description = 'Fishers Island Club is a coastal gem—remote and romantic. Playing here feels like stepping into a time capsule lined with ocean spray.'
WHERE name = 'Fishers Island Club' AND country = 'United States';

